// gateway aggregation route, runs inside the gateway layer
app.get('/api/product/:id', async (req, res) => {
  const { id } = req.params;

  const [catalogRes, pricingRes] = await Promise.all([
    fetch(`http://catalog-svc.internal:8080/items/${id}`),
    fetch(`http://pricing-svc.internal:8080/prices/${id}`),
  ]);

  if (!catalogRes.ok || !pricingRes.ok) {
    return res.status(502).json({ error: 'upstream service unavailable' });
  }

  const catalog = await catalogRes.json();
  const pricing = await pricingRes.json();

  return res.json({
    id: catalog.id,
    name: catalog.name,
    description: catalog.description,
    price: pricing.currentPrice,
    currency: pricing.currency,
  });
});

